const item = $input.first().json.body;
const category = item.category || 'other';
const priority = item.priority || 'medium';
const userLabel = item.userName ? item.userName + ' (' + (item.userEmail || '') + ')' : (item.userEmail || 'usuario');
const prompt = 'Eres un asistente de soporte TI. Clasifica la incidencia que te dan y responde SOLO con un JSON valido (sin texto adicional) con estas claves: category (una de: hardware, software, network, access, email, security, printers, systems, other), subcategory (subcategoria corta en minusculas, ej: wifi, laptop, outlook, credenciales, impresora), priority (una de: low, medium, high, critical), summary (resumen de 8 a 15 palabras), problem_type (tipo corto de problema, ej: connectivity, auth, performance, hardware_failure), suggested_solution (posible solucion en espanol, 1 a 2 frases).

Ticket: ' + item.ticketNumber + '
Titulo: ' + item.title + '
Descripcion: ' + item.description + '
Categoria declarada por el usuario: ' + category + '
Prioridad declarada por el usuario: ' + priority + '
Departamento: ' + (item.department || 'N/D') + '
Usuario: ' + userLabel;
return [{ json: Object.assign({}, item, { prompt: prompt }) }];

const original = $('Preparar analisis').first().json;
const res = $input.first().json;
const candidates = res && res.candidates ? res.candidates : [];
const parts = candidates[0] && candidates[0].content ? candidates[0].content.parts : [];
const rawText = parts[0] && parts[0].text ? parts[0].text : '';
let ai = {};
try { ai = JSON.parse(rawText); } catch (e) { ai = {}; }
const allowedCategories = ['hardware', 'software', 'network', 'access', 'email', 'security', 'printers', 'systems', 'other'];
const allowedPriorities = ['low', 'medium', 'high', 'critical'];
const safeCategory = allowedCategories.includes(String(ai.category).toLowerCase()) ? String(ai.category).toLowerCase() : String(original.category || 'other').toLowerCase();
const safePriority = allowedPriorities.includes(String(ai.priority).toLowerCase()) ? String(ai.priority).toLowerCase() : String(original.priority || 'medium').toLowerCase();
const subcategory = String(ai.subcategory || '').slice(0, 40);
const summary = String(ai.summary || original.title || '').slice(0, 200);
const problemType = String(ai.problem_type || 'general').slice(0, 40);
const solution = String(ai.suggested_solution || '').slice(0, 500);
const now = new Date().toISOString();
const body = { fields: { aiAnalysis: { mapValue: { fields: { category: { stringValue: safeCategory }, subcategory: { stringValue: subcategory }, priority: { stringValue: safePriority }, summary: { stringValue: summary }, problem_type: { stringValue: problemType }, suggested_solution: { stringValue: solution }, model: { stringValue: 'gemini-flash-latest' }, analyzedAt: { timestampValue: now } } } }, updatedAt: { timestampValue: now } } };
return [{ json: { ticketId: original.ticketId, body: body } }];

const crypto = require('crypto');
const https = require('https');

const sa = JSON.parse($env.GOOGLE_SERVICE_ACCOUNT_JSON);

function httpsRequest(options, body) {
  return new Promise((resolve, reject) => {
    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });
    req.on('error', reject);
    if (body) req.write(body);
    req.end();
  });
}

const now = Math.floor(Date.now() / 1000);
const header = Buffer.from(JSON.stringify({ alg: 'RS256', typ: 'JWT' })).toString('base64url');
const claims = Buffer.from(JSON.stringify({
  iss: sa.client_email,
  scope: 'https://www.googleapis.com/auth/datastore',
  aud: sa.token_uri,
  iat: now,
  exp: now + 3600,
})).toString('base64url');
const signature = crypto.sign('sha256', Buffer.from(header + '.' + claims), sa.private_key);
const jwt = header + '.' + claims + '.' + signature.toString('base64url');

const form = 'grant_type=urn%3Aietf%3Aparams%3Aoauth%3Agrant-type%3Ajwt-bearer&assertion=' + encodeURIComponent(jwt);

const tokenUri = sa.token_uri.replace(/^https?:\/\//, '');
const tokenHost = tokenUri.split('/')[0];
const tokenPath = tokenUri.slice(tokenUri.indexOf('/'));
const tokenRes = await httpsRequest({ method: 'POST', hostname: tokenHost, path: tokenPath, headers: { 'Content-Type': 'application/x-www-form-urlencoded', 'Content-Length': Buffer.byteLength(form) } }, form);
const tokenData = JSON.parse(tokenRes.body);
if (!tokenData.access_token) {
  throw new Error('No access token: ' + tokenRes.status + ' ' + tokenRes.body.slice(0, 300));
}

const ticketId = $json.ticketId;
if (!ticketId) {
  throw new Error('ticketId no disponible');
}

if (!$json.body || !$json.body.fields) {
  throw new Error('body Firestore no disponible en la salida de Extraer y validar');
}
const body = JSON.stringify($json.body);
const path = '/v1/projects/' + sa.project_id + '/databases/(default)/documents/tickets/' + ticketId + '?updateMask.fieldPaths=aiAnalysis&updateMask.fieldPaths=updatedAt';
const fireRes = await httpsRequest({ method: 'PATCH', hostname: 'firestore.googleapis.com', path, headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + tokenData.access_token, 'Content-Length': Buffer.byteLength(body) } }, body);

if (fireRes.status !== 200) {
  throw new Error('Firestore PATCH ' + fireRes.status + ': ' + fireRes.body.slice(0, 300));
}

return { success: true, ticketId, firestoreStatus: fireRes.status };
